#include "api7_selective_journal.hpp"
namespace api7 { std::expected<void,std::string> SelectiveJournal::begin()noexcept{if(!api_||std::this_thread::get_id()!=owner_)return std::unexpected("same-thread contract"); auto h=api_->BeginSelectiveStateJournal();if(FAILED(h))return std::unexpected("begin failed");active_=true;return{};} std::expected<void,std::string> SelectiveJournal::capture(bool on)noexcept{if(!active_||std::this_thread::get_id()!=owner_)return std::unexpected("inactive or wrong thread");if(FAILED(api_->SetStateJournalCaptureEnabled(on)))return std::unexpected("capture failed");return{};} std::expected<void,std::string> SelectiveJournal::restore()noexcept{if(!active_||std::this_thread::get_id()!=owner_)return std::unexpected("inactive or wrong thread");auto h=api_->RestoreStateJournal();active_=false;if(FAILED(h))return std::unexpected("restore failed (reset invalidates journal)");return{};} }
